cat > src/services/auth-service.js <<'EOF'
import { UserRepository } from '../repositories/user-repository.js';

const users = new UserRepository();

export async function findByEmail(email) {
  const rows = await users.findActive();
  return rows.find((u) => u.email === email) ?? null;
}

export async function isActive(email) {
  return Boolean(await findByEmail(email));
}
EOF
cat > tests/auth-service.test.js <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { findByEmail, isActive } from '../src/services/auth-service.js';

test('findByEmail ignores soft-deleted users', async () => {
  assert.equal(await findByEmail('alan@example.com'), null);
});

test('isActive is true for a live user', async () => {
  assert.equal(await isActive('ada@example.com'), true);
});
EOF
node --test tests/auth-service.test.js 2>&1 | tail -15
mkdir -p .agent-work/migration && cat > .agent-work/migration/auth-service.md <<'EOF'
# auth-service migration
- Replaced direct db `query` with UserRepository.findActive(); email match done in service (no findByEmail in repo or mapping table).
- findByEmail/isActive now return promises; tests updated to async/await.
- Tests: node --test tests/auth-service.test.js
EOF
